-- Add the shared catalog without changing existing profiles, assignments or prices.

CREATE TABLE IF NOT EXISTS organization_services (organization_id TEXT NOT NULL REFERENCES organizations(id), service_id TEXT NOT NULL REFERENCES services(id), PRIMARY KEY(organization_id,service_id));
CREATE INDEX IF NOT EXISTS idx_organization_services_service ON organization_services(service_id,organization_id);
-- Reconcile only existing, valid service IDs. Do not infer assignments from category.
INSERT OR IGNORE INTO caregiver_services(caregiver_id,service_id) SELECT c.id,j.value FROM caregivers c,json_each(COALESCE(c.services_offered,'[]')) j JOIN services s ON s.id=j.value;
CREATE INDEX IF NOT EXISTS idx_reviews_eligible ON reviews(caregiver_id,is_verified_review,is_hidden,booking_id,rating);
